package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {





    @Test
    public void testIsNumber_Hexadecimal() {
        assertTrue("Simple hex", NumberUtils.isNumber("0x123"));
        assertTrue("Hex with upper case", NumberUtils.isNumber("0xABC"));
        assertTrue("Hex with mixed case", NumberUtils.isNumber("0x1aF"));
        assertFalse("Incomplete hex", NumberUtils.isNumber("0x"));
        assertFalse("Invalid hex char", NumberUtils.isNumber("0xG"));
        assertFalse("Negative hex (not supported by logic)", NumberUtils.isNumber("-0x123"));
    }










}

