import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {







    @Test
    public void testIsNumber_Decimals() {
        assertTrue("Decimal point", NumberUtils.isNumber("123.45"));
        assertTrue("Trailing decimal point", NumberUtils.isNumber("123."));
        assertTrue("Decimal with negative sign", NumberUtils.isNumber("-123.45"));
        assertFalse("Double decimal point", NumberUtils.isNumber("12.3.4"));
        assertFalse("Only decimal point", NumberUtils.isNumber("."));
        assertFalse("Decimal in exponent", NumberUtils.isNumber("1e2.3"));
    }








}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {









    @Test
    public void testIsNumber_Exponents() {
        assertTrue("Scientific notation", NumberUtils.isNumber("1e10"));
        assertTrue("Scientific notation upper", NumberUtils.isNumber("1E10"));
        assertTrue("Scientific notation negative exponent", NumberUtils.isNumber("1e-10"));
        assertTrue("Scientific notation positive exponent", NumberUtils.isNumber("1e+10"));
        assertTrue("Decimal before exponent", NumberUtils.isNumber("1.2e10"));
        assertFalse("Exponent without leading digit", NumberUtils.isNumber("e10"));
        assertFalse("Trailing exponent", NumberUtils.isNumber("123e"));
        assertFalse("Double exponent", NumberUtils.isNumber("1e2e3"));
        assertFalse("Sign without digit after E", NumberUtils.isNumber("1e+"));
        assertFalse("Sign without digit after E middle", NumberUtils.isNumber("1e+-1"));
    }






}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {











    @Test
    public void testIsNumber_TypeQualifiers() {
        // d, D, f, F (Double/Float)
        assertTrue("Float suffix f", NumberUtils.isNumber("123.45f"));
        assertTrue("Float suffix F", NumberUtils.isNumber("123.45F"));
        assertTrue("Double suffix d", NumberUtils.isNumber("123.45d"));
        assertTrue("Double suffix D", NumberUtils.isNumber("123.45D"));
        assertTrue("Float suffix with integer", NumberUtils.isNumber("123f"));

        // l, L (Long)
        assertTrue("Long suffix l", NumberUtils.isNumber("123l"));
        assertTrue("Long suffix L", NumberUtils.isNumber("123L"));
        assertFalse("Long suffix with exponent", NumberUtils.isNumber("1e10l"));
        assertFalse("Long suffix with exponent upper", NumberUtils.isNumber("1E10L"));

        // Invalid qualifiers
        assertFalse("Invalid suffix", NumberUtils.isNumber("123x"));
        assertFalse("Invalid suffix decimal", NumberUtils.isNumber("123.45z"));
    }




}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {













    @Test
    public void testIsNumber_EdgeCases() {
        assertFalse("Non-numeric string", NumberUtils.isNumber("abc"));
        assertFalse("Mixed alpha-numeric", NumberUtils.isNumber("12a3"));
        assertFalse("Space in string", NumberUtils.isNumber("12 3"));
        assertFalse("Special characters", NumberUtils.isNumber("!@#"));

        // Testing the branch: (i < sz + 1 && allowSigns && !foundDigit)
        // This handles cases like "1e+" where i reaches the end and allowSigns is true
        assertFalse("Incomplete exponent sign", NumberUtils.isNumber("1e+"));

        // Testing the branch: (i < chars.length) at the end
        assertTrue("Integer with sign", NumberUtils.isNumber("1"));
        assertFalse("Single dash", NumberUtils.isNumber("-"));
    }


}

package org.apache.commons.lang3.math;

import java.io.*;
import java.math.*;
