import java.math.BigInteger;
import java.util.*;
import org.apache.commons.lang3.StringUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class NumberUtils_isNumber_TriageGen1Test {















    @Test
    public void testIsNumber_ComplexityCombinations() {
        assertTrue("Complex valid", NumberUtils.isNumber("-1.23E+4f"));
        assertTrue("Complex valid hex", NumberUtils.isNumber("0x123"));
        assertFalse("Invalid complex", NumberUtils.isNumber("-1.2.3E4"));
        assertFalse("Invalid complex sign", NumberUtils.isNumber("1e--2"));
    }
}
